begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('93000000-0000-4000-8000-000000000001','invoice-doc-staff@example.test','{}'),('93000000-0000-4000-8000-000000000002','invoice-doc-inactive@example.test','{}');
update public.profiles set is_active = true where id in ('93000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000002');
insert into public.user_roles (user_id, role) values ('93000000-0000-4000-8000-000000000001','STAFF'),('93000000-0000-4000-8000-000000000002','STAFF');

update public.profiles set is_active=false where id='93000000-0000-4000-8000-000000000002';
create temp table fx(k text primary key,id uuid); grant all on fx to authenticated;
create temp table documents(k text primary key,v jsonb); grant all on documents to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"93000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from public.save_client(auth.uid(),null,null,'Invoice','Family','private@example.test',null,'EMAIL','123 Mailing Way','Private Housecall Address');
insert into fx select 'other',id from public.save_client(auth.uid(),null,null,'Other','Family',null,null,'EMAIL',null,null);
insert into fx select 'product',id from public.save_catalog_product(null,null,'Exam <script>','service','','visit',1001,true);
select public.create_billing_invoice('94000000-0000-4000-8000-000000000001',(select id from fx where k='client'));
select public.add_invoice_service('94000000-0000-4000-8000-000000000002','94000000-0000-4000-8000-000000000001',null,(select id from fx where k='product'),1.5);
insert into documents select 'draft',public.read_invoice_document('94000000-0000-4000-8000-000000000001',(select id from fx where k='client'));
select is((select v->>'status' from documents where k='draft'),'draft','Draft is explicitly identified');
select is((select v->>'total_cents' from documents where k='draft'),'1502','Rounding comes from stored exact charge');
select is((select v#>>'{items,0,quantity}' from documents where k='draft'),'1.500','Quantity precision retained');
select is((select v#>>'{items,0,unit_price_cents}' from documents where k='draft'),'1001','Money serialized as decimal text');
select is((select v#>>'{client,mailing_address}' from documents where k='draft'),'123 Mailing Way','Mailing address included');
select ok((select not (v::text like '%private@example.test%' or v::text like '%Private Housecall Address%') from documents where k='draft'),'Contact and housecall address not released');
select throws_ok($$select public.read_invoice_document('94000000-0000-4000-8000-000000000001',(select id from fx where k='other'))$$,'42501','Invoice not available for this household','Wrong household rejected');
select throws_ok($$select public.read_invoice_document(gen_random_uuid(),(select id from fx where k='client'))$$,'42501',null,'Missing invoice fails closed');
select public.issue_billing_invoice('94000000-0000-4000-8000-000000000001',2);
select public.credit_billing_invoice('94000000-0000-4000-8000-000000000003','94000000-0000-4000-8000-000000000001',29,'INTERNAL CREDIT REASON');
insert into documents select 'issued',public.read_invoice_document('94000000-0000-4000-8000-000000000001',(select id from fx where k='client'));
select is((select v->>'status' from documents where k='issued'),'issued','Issued status returned');
select is((select v->>'total_cents' from documents where k='issued'),'1502','Credit preserves original total');
select is((select v#>>'{credits,0,amount_cents}' from documents where k='issued'),'29','Credit separately included');
select ok((select v->>'issued_at' is not null from documents where k='issued'),'Issued time included');
select ok((select v::text not like '%INTERNAL CREDIT REASON%' from documents where k='issued'),'Internal credit reason omitted');
select ok((select not (v ? 'created_by' or v ? 'void_reason' or v ? 'payment_status') from documents where k='issued'),'No staff notes or invented payment status');
select public.create_billing_invoice('94000000-0000-4000-8000-000000000004',(select id from fx where k='client'));
select public.add_invoice_service('94000000-0000-4000-8000-000000000005','94000000-0000-4000-8000-000000000004',null,(select id from fx where k='product'),1);
select public.issue_billing_invoice('94000000-0000-4000-8000-000000000004',2);
select public.void_billing_invoice('94000000-0000-4000-8000-000000000004',3,'INTERNAL VOID REASON');
insert into documents select 'void',public.read_invoice_document('94000000-0000-4000-8000-000000000004',(select id from fx where k='client'));
select is((select v->>'status' from documents where k='void'),'void','Voided status returned');
select ok((select v->>'voided_at' is not null and v::text not like '%INTERNAL VOID REASON%' from documents where k='void'),'Void date without internal reason');
select set_config('request.jwt.claims','{"sub":"93000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.read_invoice_document('94000000-0000-4000-8000-000000000001',(select id from fx where k='client'))$$,'42501','Active staff access required','Inactive staff denied');
set local role anon;
select throws_ok($$select public.read_invoice_document(gen_random_uuid(),gen_random_uuid())$$,'42501',null,'Anonymous denied');
set local role service_role;
select throws_ok($$select public.read_invoice_document(gen_random_uuid(),gen_random_uuid())$$,'42501',null,'Service role has no document export permission');
reset role;
select * from finish();
rollback;
